/// <summary>
/// This is a data contract class for the business event <c>METPicklistExtractionBusinessEvent</c>.
/// </summary>
[DataContract]
final class METPicklistExtractionBusinessEventContract extends BusinessEventsContract
{
    #define.LegalEntity('LegalEntity')
    #define.PickingListNumber('PickingListNumber')
    #define.CreatedBy('CreatedBy')
    #define.InventLocationId('Warehouse')
    #define.InventSiteId('InventSiteId')

    private LegalEntityDataAreaId   legalEntity;
    private WMSPickingRouteID       pickingRouteId;
    private CreatedBy               createdBy;
    private InventLocationId        inventLocationId;
    private InventSiteId            inventSiteId;

}

