/// <summary>
///  Constructs a <c>METPicklistExtractionBusinessEventContract</c>.
/// </summary>
/// <param name = "_wmsPickingRoute">
/// <c>WMSPickingRoute</c> record.
/// </param>
/// <returns>An instance of <c>METPicklistExtractionBusinessEventContract</c>.</returns>
public static METPicklistExtractionBusinessEventContract newFromWMSPickingRoute(WMSPickingRoute _wmsPickingRoute)
{
    METPicklistExtractionBusinessEventContract contract = new METPicklistExtractionBusinessEventContract();
    contract.initialize(_wmsPickingRoute);
    return contract;
}

/// <summary>
/// Initializes data variables.
/// </summary>
/// <param name = "_wmsPickingRoute">
/// <c>WMSPickingRoute</c> record.
/// </param>
private void initialize(WMSPickingRoute _wmsPickingRoute)
{
    legalEntity    = curExt();
    pickingRouteId = _wmsPickingRoute.pickingRouteID;
    createdBy      = _wmsPickingRoute.CreatedBy;
    inventLocationId = _wmsPickingRoute.InventLocationId;
    inventSiteId    = InventLocation::find(inventLocationId).InventSiteId;
}

/// <summary>
/// Gets and sets legal entity.
/// </summary>
/// <param name = "_legalEntity">Legal entity.</param>
/// <returns>Legal entity.</returns>
[DataMember(#LegalEntity), BusinessEventsDataMember("@ProcurementAndSourcing:LegalEntity")]
public LegalEntityDataAreaId parmLegalEntity(LegalEntityDataAreaId _legalEntity = legalEntity)
{
    legalEntity = _legalEntity;
    return legalEntity;
}

